messages.content:
Family: conversations. Agent calls and meetings: turns per speaker, resolution, and a summary {headline, points, decisions, actions}. Keep placeholders such as {value}.

Return JSON with a `records` array of 9 records in exactly this shape. Every record must keep `synthetic: true`. Example (the current hand-written seed):

[
 {
  "id": "cv-my-overpressure",
  "kind": "meeting",
  "scenarioId": "my-overpressure",
  "convener": "myer-manager",
  "participants": [
   "myer-manager",
   "myer-engineer",
   "myer-compliance",
   "myer-technician"
  ],
  "topic": "PG-601 overpressure on the primary circuit",
  "issueKind": "overpressure",
  "turns": [
   {
    "speaker": "myer-manager",
    "text": "Call convened on PG-601: {value} bar against the 3.5 bar limit. Engineer first, then compliance, then the technician."
   },
   {
    "speaker": "myer-engineer",
    "text": "PG-601 has risen from 3.2 to {value} bar in 40 minutes. P-101 is running and TK-201 is the likely cause: a low membrane pre-charge. Isolate at V-501 and open the bypass before the relief valve lifts at 3.8 bar."
   },
   {
    "speaker": "myer-compliance",
    "text": "TK-201's inspection plan records 3.5 bar as the circuit's limit. Plant running outside its safe limits is a risk we must control and then review under the Victorian OHS Regulations (regs 97, 98 and 121), and the inspection and the fix go in the plant record (regs 105 and 106)."
   },
   {
    "speaker": "myer-technician",
    "text": "I can reach {contactName} ({contactRole}) by {contactChannel} through the dispatch line; nobody else on shift has contact details on file."
   }
  ],
  "resolution": "Isolate the primary circuit at V-501 and open the bypass; {contactName} attends to check the TK-201 pre-charge and confirm PG-601 back below 3.5 bar.",
  "summary": {
   "headline": "PG-601 at {value} bar: isolate at V-501, duty engineer to attend",
   "points": [
    "PG-601 rose from 3.2 to {value} bar over 40 minutes on a 3.5 bar circuit.",
    "TK-201's membrane pre-charge is the likely cause.",
    "Only the duty engineer has contact details on file."
   ],
   "decisions": [
    "Isolate the primary circuit at V-501 and open the bypass.",
    "Duty engineer attends to check the TK-201 pre-charge."
   ],
   "actions": [
    {
     "owner": "Field Technician · Myer",
     "task": "Text {contactName} through the dispatch line",
     "due": "now"
    },
    {
     "owner": "{contactName}",
     "task": "Check TK-201 pre-charge and confirm PG-601 below 3.5 bar",
     "due": "within 1 hour"
    }
   ]
  },
  "synthetic": true,
  "generator": "hand-seed"
 },
