  "callee": "myer-compliance",
  "participants": [
   "bristol-compliance",
   "myer-compliance"
  ],
  "topic": "Shared pressure-equipment examiner",
  "turns": [
   {
    "speaker": "bristol-compliance",
    "text": "Bristol's PV-301 examination certificate has expired and our public steam demonstration is blocked. When is Myer's pressure-equipment examiner next on site, and do you hold a written scheme template we could adapt?"
   },
   {
    "speaker": "myer-compliance",
    "text": "Our examiner is booked for TK-201 on {myerExamDate}. Victoria has no written-scheme rule, but we keep an inspection plan and maintenance record for TK-201 (MY-IMR-TK201-2026); I will email it as a starting point. Your PV-301 scheme must still be drawn up or certified as suitable by a competent person under PSSR regulation 8."
   },
   {
    "speaker": "bristol-compliance",
    "text": "Thank you. If the examiner can also cover PV-301 and the V-505 lift test, we clear the demonstration in one visit. I will ask our manager to agree it with yours."
   }
  ],
  "summary": {
   "headline": "Compliance officers line up one examiner for both factories",
   "points": [
    "Myer's examiner is booked for TK-201 on {myerExamDate}.",
    "Myer shares its TK-201 inspection plan as a starting point; PV-301's written scheme needs a competent person (PSSR reg 8)."
   ],
   "decisions": [
    "Ask the managers to share one examiner visit."
   ],
   "actions": [
    {
     "owner": "Compliance Officer · Myer",
     "task": "Email the TK-201 inspection plan to Bristol",
     "due": "today"
    },
    {
     "owner": "Plant Manager · Bristol",
     "task": "Agree a shared visit with Myer",
     "due": "today"
